async function activateView(page: Page, view: (typeof exactViews)[number]) {
  const viewButton = page.getByRole("button", { name: view, exact: true });
  await viewButton.click();
  await expect(viewButton).toHaveAttribute("aria-current", "page");
  await expect(page.getByRole("heading", { level: 1, name: view, exact: true })).toBeVisible();
  return viewButton;
}

async function pressNamedButton(page: Page, name: string) {
  const button = page.getByRole("button", { name, exact: true });
  await button.focus();
  await expect(button).toBeFocused();
  await page.keyboard.press("Enter");
}

async function expectVisibleFocus(locator: Locator) {
  await expect(locator).toBeFocused();
  const focusStyle = await locator.evaluate((node) => {
    const style = getComputedStyle(node);
    return { outlineStyle: style.outlineStyle, outlineWidth: style.outlineWidth };
  });
  expect(focusStyle.outlineStyle).not.toBe("none");
  expect(Number.parseFloat(focusStyle.outlineWidth)).toBeGreaterThanOrEqual(3);
}

function sourceHead() {
  const head = process.env.CLOVER_TREE_HEAD ?? execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  if (!/^[0-9a-f]{40}$/u.test(head)) throw new Error(`Invalid Clover Tree source head: ${head}`);
  return head;
}

function sha256(bytes: string | Buffer) {
  return createHash("sha256").update(bytes).digest("hex");
}

async function collectDecorativeBindings(page: Page): Promise<DecorativeBindings> {
  const entries = await page.evaluate((views): DecorativeBindingEntry[] => {
    const interactiveSelector = 'a[href], button, input, select, textarea, [contenteditable="true"], [tabindex]:not([tabindex="-1"]), [role]:not([role="presentation"]):not([role="none"])';
    const leaves = document.querySelectorAll('.tree-mark-leaf[aria-hidden="true"]');
    if (leaves.length !== 1 || !(leaves[0] instanceof HTMLElement)) throw new Error(`tree-mark-leaf-match-count:${leaves.length}`);
    const leaf = leaves[0];
    if (leaf.outerHTML !== '<span class="tree-mark-leaf" aria-hidden="true">⌁</span>' || leaf.textContent?.trim() !== "⌁" || leaf.childElementCount !== 0 || leaf.querySelectorAll(interactiveSelector).length !== 0) throw new Error("tree-mark-leaf-predicate-mismatch");
    const collected: DecorativeBindingEntry[] = [{
      kind: "tree-mark-leaf", predicate: "tree-mark-leaf-glyph", sourceBucket: "live-dom-decorative-binding",
      selector: '.tree-mark-leaf[aria-hidden="true"]', ordinal: null, accessibleName: null, matchCount: 1,
      outerHTML: leaf.outerHTML, parentOuterHTML: null, childElementCount: 0, interactiveDescendantCount: 0
    }];
    const buttons = [...document.querySelectorAll(".command-sidebar nav button")];
    if (buttons.length !== views.length || buttons.some((button) => !(button instanceof HTMLButtonElement))) throw new Error(`sidebar-button-match-count:${buttons.length}`);
    for (const [index, accessibleName] of views.entries()) {
      const ordinal = String(index + 1).padStart(2, "0");
      const button = buttons[index] as HTMLButtonElement;
      const markers = button.querySelectorAll(':scope > span[aria-hidden="true"]');
      if (markers.length !== 1 || !(markers[0] instanceof HTMLElement)) throw new Error(`sidebar-ordinal-${ordinal}-match-count:${markers.length}`);
      const marker = markers[0];
      const nameClone = button.cloneNode(true) as HTMLButtonElement;
      nameClone.querySelectorAll('[aria-hidden="true"]').forEach((node) => node.remove());
      const accessibleTextAlternative = nameClone.textContent?.trim() ?? "";
      if (accessibleTextAlternative !== accessibleName || button.hasAttribute("aria-label") || button.hasAttribute("aria-labelledby")) throw new Error(`sidebar-ordinal-${ordinal}-accessible-name-mismatch:${accessibleTextAlternative}`);
      if (marker.outerHTML !== `<span aria-hidden="true">${ordinal}</span>` || marker.textContent?.trim() !== ordinal || marker.childElementCount !== 0 || marker.querySelectorAll(interactiveSelector).length !== 0) throw new Error(`sidebar-ordinal-${ordinal}-predicate-mismatch`);
      const currentAttribute = button.getAttribute("aria-current");
      if (currentAttribute !== null && currentAttribute !== "page") throw new Error(`sidebar-ordinal-${ordinal}-aria-current:${currentAttribute}`);
      const expectedParent = `<button type="button"${currentAttribute === "page" ? ' aria-current="page"' : ""}><span aria-hidden="true">${ordinal}</span>${accessibleName}</button>`;
      if (button.outerHTML !== expectedParent) throw new Error(`sidebar-ordinal-${ordinal}-parent-html-mismatch`);
      collected.push({
        kind: "navigation-ordinal", predicate: "sidebar-navigation-ordinal", sourceBucket: "live-dom-decorative-binding",
        selector: '.command-sidebar nav button > span[aria-hidden="true"]', ordinal, accessibleName, matchCount: 1,
        outerHTML: marker.outerHTML, parentOuterHTML: button.outerHTML, childElementCount: 0, interactiveDescendantCount: 0
      });
    }
    return collected;
  }, [...exactViews]);
  const body = { sourceBucket: "live-dom-decorative-binding" as const, entries };
  return { ...body, canonicalSha256: sha256(`${canonicalJson(body)}\n`) };
}

function ruleMessageData(node: AxeNode) {
  const check = [...node.any, ...node.all, ...node.none].find(({ id }) => id === "color-contrast") ?? node.any[0] ?? node.all[0] ?? node.none[0];
  const data = check?.data && typeof check.data === "object" ? check.data as Record<string, unknown> : {};
  const expected = typeof data.expectedContrastRatio === "string" ? Number.parseFloat(data.expectedContrastRatio) : 4.5;
  return {
    messageKey: typeof data.messageKey === "string" ? data.messageKey : null,
    threshold: Number.isFinite(expected) ? expected : 4.5
  };
}

async function adjudicateIncompleteNode(page: Page, ruleId: string, node: AxeNode): Promise<ContrastAdjudication> {
  const target = (node.target as unknown[]).map((part) => {
    if (typeof part !== "string") throw new Error(`Unsupported non-string Axe target: ${JSON.stringify(node.target)}`);
    return part;
  });
  const { messageKey, threshold } = ruleMessageData(node);
  if (ruleId !== "color-contrast") {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: null, background: null,
      ratio: null, threshold: null, passes: false, targetMatch: { count: 0, outerHTML: null, exact: false },
      exemption: null, unresolvedReason: `unsupported-incomplete-rule:${ruleId}`
    };
  }
  if (target.length !== 1) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: null, background: null,
      ratio: null, threshold, passes: false, targetMatch: { count: 0, outerHTML: null, exact: false },
      exemption: null, unresolvedReason: "compound-or-shadow-target"
    };
  }

  const measurement = await page.evaluate(({ selector, expectedViews }) => {
    type Rgba = { r: number; g: number; b: number; a: number };
    const parseColor = (value: string): Rgba | null => {
      const match = value.match(/^rgba?\(\s*([\d.]+)[, ]+\s*([\d.]+)[, ]+\s*([\d.]+)(?:\s*[,/]\s*([\d.]+))?\s*\)$/u);
      if (!match) return null;
      return { r: Number(match[1]), g: Number(match[2]), b: Number(match[3]), a: match[4] === undefined ? 1 : Number(match[4]) };
    };
    const composite = (foreground: Rgba, background: Rgba): Rgba => {
      const alpha = foreground.a + background.a * (1 - foreground.a);
      if (alpha === 0) return { r: 0, g: 0, b: 0, a: 0 };
      return {
        r: (foreground.r * foreground.a + background.r * background.a * (1 - foreground.a)) / alpha,
        g: (foreground.g * foreground.a + background.g * background.a * (1 - foreground.a)) / alpha,
        b: (foreground.b * foreground.a + background.b * background.a * (1 - foreground.a)) / alpha,
        a: alpha
      };
    };
    const serialize = ({ r, g, b, a }: Rgba) => `rgba(${r}, ${g}, ${b}, ${a})`;
    let matches: NodeListOf<Element>;
    try {
      matches = document.querySelectorAll(selector);
    } catch {
      return { error: "invalid-target-selector", matchCount: 0, outerHTML: null };
    }
    if (matches.length !== 1 || !(matches[0] instanceof HTMLElement)) {
      return { error: `target-match-count:${matches.length}`, matchCount: matches.length, outerHTML: null };
    }
    const element = matches[0];
    const interactiveDescendantCount = element.querySelectorAll('a[href], button, input, select, textarea, [contenteditable="true"], [tabindex]:not([tabindex="-1"]), [role]:not([role="presentation"]):not([role="none"])').length;
    const text = element.textContent?.trim() ?? "";
    const noMeaningfulOrInteractiveDescendants = element.childElementCount === 0 && interactiveDescendantCount === 0;
    const parent = element.parentElement;
    const parentText = parent?.textContent?.trim() ?? "";
    const navigationName = parentText.startsWith(text) ? parentText.slice(text.length).trim() : "";
    const treeLeafDecoration = selector === ".tree-mark-leaf"
      && element.matches('span.tree-mark-leaf[aria-hidden="true"]')
      && text === "⌁"
      && noMeaningfulOrInteractiveDescendants;
    const navigationOrdinalDecoration = element.matches('.command-sidebar nav button > span[aria-hidden="true"]')
      && /^\d{2}$/u.test(text)
      && parent instanceof HTMLButtonElement
      && (expectedViews as readonly string[]).includes(navigationName)
      && noMeaningfulOrInteractiveDescendants;
    const layers: Rgba[] = [];
    const backgroundImages: string[] = [];
    const nonUnitOpacity: Array<{ selector: string; opacity: number }> = [];
    for (let current: HTMLElement | null = element; current; current = current.parentElement) {
      const style = getComputedStyle(current);
      const color = parseColor(style.backgroundColor);
      if (!color) return { error: `unparseable-background:${style.backgroundColor}` };
      layers.unshift(color);
      if (style.backgroundImage !== "none") backgroundImages.push(style.backgroundImage);
      const opacity = Number.parseFloat(style.opacity);
      if (!Number.isFinite(opacity)) return { error: `unparseable-opacity:${style.opacity}` };
      if (opacity !== 1) nonUnitOpacity.push({ selector: current.tagName.toLowerCase(), opacity });
    }
    let background: Rgba = { r: 8, g: 17, b: 13, a: 1 };
    for (const layer of layers) background = composite(layer, background);
    const foregroundSource = parseColor(getComputedStyle(element).color);
    if (!foregroundSource) return { error: `unparseable-foreground:${getComputedStyle(element).color}` };
    const foreground = composite(foregroundSource, background);
    const linear = (channel: number) => {
      const normalized = channel / 255;
      return normalized <= 0.04045 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
    };
    const luminance = (color: Rgba) => 0.2126 * linear(color.r) + 0.7152 * linear(color.g) + 0.0722 * linear(color.b);
    const foregroundLuminance = luminance(foreground);
    const backgroundLuminance = luminance(background);
    const ratio = (Math.max(foregroundLuminance, backgroundLuminance) + 0.05) / (Math.min(foregroundLuminance, backgroundLuminance) + 0.05);
    return {
      error: null,
      matchCount: matches.length,
      outerHTML: element.outerHTML,
      text,
      elementAriaHidden: element.getAttribute("aria-hidden") === "true",
      noMeaningfulOrInteractiveDescendants,
      treeLeafDecoration,
      navigationOrdinalDecoration,
      foreground: serialize(foreground),
      background: serialize(background),
      ratio,
      backgroundImages,
      nonUnitOpacity
    };
  }, { selector: target[0]!, expectedViews: [...exactViews] });

  const targetMatch = {
    count: measurement.matchCount ?? 0,
    outerHTML: measurement.outerHTML ?? null,
    exact: measurement.matchCount === 1 && measurement.outerHTML === node.html
  };

  if (measurement.error) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: null, background: null,
      ratio: null, threshold, passes: false, targetMatch, exemption: null, unresolvedReason: measurement.error
    };
  }
  if (!targetMatch.exact) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: measurement.foreground!, background: measurement.background!,
      ratio: measurement.ratio!, threshold, passes: false, targetMatch, exemption: null, unresolvedReason: "axe-target-html-substitution"
    };
  }
  if (measurement.treeLeafDecoration) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "decorative-tree-mark-leaf", foreground: measurement.foreground!, background: measurement.background!,
      ratio: measurement.ratio!, threshold, passes: true, targetMatch,
      exemption: {
        kind: "decorative-tree-mark-leaf", predicate: "tree-mark-leaf-glyph",
        basis: "exact aria-hidden Clover leaf glyph is ornamental and contains no meaningful or interactive descendants",
        noMeaningfulOrInteractiveDescendants: true
      },
      unresolvedReason: null
    };
  }
  if (measurement.navigationOrdinalDecoration) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "decorative-navigation-ordinal", foreground: measurement.foreground!, background: measurement.background!,
      ratio: measurement.ratio!, threshold, passes: true, targetMatch,
      exemption: {
        kind: "decorative-navigation-ordinal", predicate: "sidebar-navigation-ordinal",
        basis: "exact two-digit aria-hidden sidebar ordinal is redundant with its adjacent complete button name and contains no meaningful or interactive descendants",
        noMeaningfulOrInteractiveDescendants: true
      },
      unresolvedReason: null
    };
  }
  if (measurement.elementAriaHidden) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: measurement.foreground!, background: measurement.background!,
      ratio: measurement.ratio!, threshold, passes: false, targetMatch, exemption: null, unresolvedReason: "aria-hidden-target-not-on-exact-decorative-allowlist"
    };
  }
  const unresolvedReason = measurement.backgroundImages!.length > 0
    ? "background-image-remains"
    : measurement.nonUnitOpacity!.length > 0
      ? "non-unit-ancestor-opacity-remains"
      : measurement.text!.length === 0
        ? "meaningful-text-not-found"
        : null;
  if (unresolvedReason) {
    return {
      ruleId, target, html: node.html, messageKey, classification: "unresolved", foreground: measurement.foreground!, background: measurement.background!,
      ratio: measurement.ratio!, threshold, passes: false, targetMatch, exemption: null, unresolvedReason
    };
  }
  return {
    ruleId, target, html: node.html, messageKey, classification: "measured-contrast", foreground: measurement.foreground!, background: measurement.background!,
    ratio: measurement.ratio!, threshold, passes: measurement.ratio! >= threshold, targetMatch, exemption: null, unresolvedReason: null
  };
}

async function scanWithCompleteAxePayload(
  page: Page,
  scans: AxeScanEvidence[],
  view: (typeof exactViews)[number],
  state: string,
  viewport: { width: number; height: number }
) {
  const decorativeBindings = await collectDecorativeBindings(page);
  const result = await new AxeBuilder({ page }).analyze();
  const adjudications: ContrastAdjudication[] = [];
  for (const rule of result.incomplete) {
    for (const node of rule.nodes) adjudications.push(await adjudicateIncompleteNode(page, rule.id, node));
  }
  const evidence = { view, state, viewport, axeVersion: result.testEngine.version, passes: result.passes, violations: result.violations, incomplete: result.incomplete, inapplicable: result.inapplicable, adjudications, decorativeBindings };
  scans.push(evidence);
  expect(result.violations, JSON.stringify(evidence, null, 2)).toEqual([]);
  expect(result.incomplete.filter(({ id }) => id !== "color-contrast"), JSON.stringify(evidence, null, 2)).toEqual([]);
  expect(adjudications.filter(({ passes }) => !passes), JSON.stringify(evidence, null, 2)).toEqual([]);
}

function sortedCanonical<T>(values: T[]) {
  return [...values].sort((left, right) => canonicalJson(left).localeCompare(canonicalJson(right)));
}

function inventoryDigests(occurrences: Gate04Occurrence[]) {
  const sortedOccurrences = sortedCanonical(occurrences);
  const selectorHtmlPairs = sortedCanonical([
    ...new Map(sortedOccurrences.map(({ selector, html }) => [canonicalJson({ selector, html }), { selector, html }])).values()
  ]);
  const selectors = [...new Set(sortedOccurrences.map(({ selector }) => selector))].sort();
  return {
    occurrences: sortedOccurrences.length,
    occurrenceSha256: sha256(`${canonicalJson(sortedOccurrences)}\n`),
    selectorHtmlPairs: selectorHtmlPairs.length,
    selectorHtmlPairSha256: sha256(`${canonicalJson(selectorHtmlPairs)}\n`),
    selectors: selectors.length,
    selectorSha256: sha256(`${canonicalJson(selectors)}\n`)
  };
}

function gate04PriorInventory() {
  const compressed = Buffer.from(gate04InventoryGzipBase64, "base64");
  if (sha256(compressed) !== gate04InventoryGzipSha256) throw new Error("Gate 0.4 compressed inventory digest mismatch");
  const canonicalBytes = gunzipSync(compressed).toString("utf8");
  const occurrences = JSON.parse(canonicalBytes) as Gate04Occurrence[];
  if (`${canonicalJson(occurrences)}\n` !== canonicalBytes) throw new Error("Gate 0.4 occurrence inventory is not canonical");
  const digests = inventoryDigests(occurrences);
  const expected = {
    occurrences: gate04OccurrenceCount,
    occurrenceSha256: gate04OccurrenceSha256,
    selectorHtmlPairs: gate04SelectorHtmlPairCount,
    selectorHtmlPairSha256: gate04SelectorHtmlPairSha256,
    selectors: gate04SelectorCount,
    selectorSha256: gate04SelectorSha256
  };
  if (canonicalJson(digests) !== canonicalJson(expected)) throw new Error(`Gate 0.4 inventory binding mismatch: ${canonicalJson(digests)}`);
  return occurrences;
}

function currentColorOccurrences(scans: AxeScanEvidence[], project: string) {
  return scans.flatMap((scan) => (["passes", "incomplete"] as const).flatMap((bucket) => scan[bucket]
    .filter(({ id }) => id === "color-contrast")
    .flatMap((rule) => rule.nodes.map((node) => {
      if (node.target.length !== 1 || typeof node.target[0] !== "string") throw new Error(`Unsupported current color target: ${JSON.stringify(node.target)}`);
      return {
        occurrence: { project, view: scan.view, state: scan.state, selector: node.target[0], html: node.html } satisfies Gate04Occurrence,
        sourceBucket: bucket
      };
    }))));
}

function exactDecorativeOccurrence(occurrence: Gate04Occurrence, phase: "prior" | "current") {
  const treeHtml = phase === "prior"
    ? '<span class="tree-mark-leaf">⌁</span>'
    : '<span class="tree-mark-leaf" aria-hidden="true">⌁</span>';
  if (occurrence.selector === ".tree-mark-leaf" && occurrence.html === treeHtml) {
    return { kind: "tree-mark-leaf" as const, predicate: "tree-mark-leaf-glyph" as const, ordinal: null, accessibleName: null, currentHtml: '<span class="tree-mark-leaf" aria-hidden="true">⌁</span>' };
  }
  const match = occurrence.html.match(/^<span aria-hidden="true">(\d{2})<\/span>$/u);
  if (!match) return null;
  const ordinalIndex = Number.parseInt(match[1]!, 10) - 1;
  const accessibleName = exactViews[ordinalIndex];
  if (!accessibleName) return null;
  const inactiveSelector = `li:nth-child(${ordinalIndex + 1}) > button > span[aria-hidden="true"]`;
  const activeSelector = 'button[aria-current="page"] > span[aria-hidden="true"]';
  if (occurrence.selector !== inactiveSelector && !(occurrence.selector === activeSelector && occurrence.view === accessibleName)) return null;
  return { kind: "navigation-ordinal" as const, predicate: "sidebar-navigation-ordinal" as const, ordinal: match[1]!, accessibleName, currentHtml: occurrence.html };
}

function exactLiveTruthTimestampOccurrence(occurrence: Gate04Occurrence) {
  const exactGithubDefinitionTarget = occurrence.state === "base-view"
    && ((occurrence.view === "Today" && occurrence.selector === "div:nth-child(2) > dd")
      || (occurrence.view === "System Health" && occurrence.selector === ".observation-grid > div:nth-child(2) > dd"));
  if (exactGithubDefinitionTarget && occurrence.html === "<dd>2026-08-26T21:00:00.000Z</dd>") {
    return { currentHtml: "<dd>2026-08-29T17:00:00.000Z</dd>", substitution: "github-observed-at-source-time-advance" as const };
  }
  const exactRequestDefinitionTarget = occurrence.state === "base-view"
    && ((occurrence.view === "Today" && occurrence.selector === "div:nth-child(3) > dd")
      || (occurrence.view === "System Health" && occurrence.selector === "div:nth-child(6) > dd"));
  if (exactRequestDefinitionTarget && occurrence.html === "<dd>2026-08-26T21:00:01.000Z</dd>") {
    return { currentHtml: "<dd>2026-08-29T17:00:01.000Z</dd>", substitution: "request-observed-at-time-advance" as const };
  }
  if (occurrence.html === "<strong>2026-08-26T21:00:00.000Z</strong>") {
    return { currentHtml: "<strong>2026-08-29T17:00:00.000Z</strong>", substitution: "github-observed-at-source-time-advance" as const };
  }
  return null;
}

function buildGate04PriorClosure(scans: AxeScanEvidence[], project: string) {
  const fullPrior = gate04PriorInventory();
  const prior = fullPrior.filter((occurrence) => occurrence.project === project);
  const projectExpectations: Record<string, ReturnType<typeof inventoryDigests>> = {
    "desktop-chromium": {
      occurrences: 3664,
      occurrenceSha256: "089afe551f39c82ef29a28500037e653662388c22d3908b723e4b28d75c6c34e",
      selectorHtmlPairs: 924,
      selectorHtmlPairSha256: gate04SelectorHtmlPairSha256,
      selectors: 795,
      selectorSha256: gate04SelectorSha256
    },
    "mobile-chromium": {
      occurrences: 3140,
      occurrenceSha256: "5f3ccf9fe9c02bcdfd0c99135a1ad65049b504dbc3e3c956d3e3a23528ab652e",
      selectorHtmlPairs: 853,
      selectorHtmlPairSha256: "9db95ea95ab737676734d28dc9ebefcb775d31a5c333658ae5f05224ef28a802",
      selectors: 724,
      selectorSha256: "0d5ad6068a7f9c5ee05c348d23636913dd7278c19d439d2b3b24bc7f9756b10c"
    }
  };
  const expectedProject = projectExpectations[project];
  if (!expectedProject || canonicalJson(inventoryDigests(prior)) !== canonicalJson(expectedProject)) throw new Error(`Gate 0.4 ${project} baseline mismatch`);

  const scansByKey = new Map<string, AxeScanEvidence>();
  for (const scan of scans) {
    const key = `${scan.view}|${scan.state}`;
    if (scansByKey.has(key)) throw new Error(`Duplicate scan while binding Gate 0.4 decorations: ${key}`);
    const bindingBody = { sourceBucket: scan.decorativeBindings.sourceBucket, entries: scan.decorativeBindings.entries };
    if (scan.decorativeBindings.sourceBucket !== "live-dom-decorative-binding" || scan.decorativeBindings.entries.length !== 12 || scan.decorativeBindings.canonicalSha256 !== sha256(`${canonicalJson(bindingBody)}\n`)) throw new Error(`Invalid per-scan decorative binding: ${key}`);
    scansByKey.set(key, scan);
  }
  const current = currentColorOccurrences(scans, project);
  const excludedAxeDecorative = current.flatMap((entry) => {
    const decoration = exactDecorativeOccurrence(entry.occurrence, "current");
    return decoration ? [{ ...entry, bindingKind: decoration.kind, bindingPredicate: decoration.predicate }] : [];
  });
  const meaningfulCurrent = current.filter(({ occurrence }) => exactDecorativeOccurrence(occurrence, "current") === null);
  const currentByKey = new Map<string, number[]>();
  meaningfulCurrent.forEach(({ occurrence }, index) => {
    const key = canonicalJson(occurrence);
    currentByKey.set(key, [...(currentByKey.get(key) ?? []), index]);
  });
  const used = new Set<number>();
  const normalizedMatched: Gate04Occurrence[] = [];
  const substitutions: Array<Gate04Occurrence & { currentHtml: string; substitution: "tree-mark-leaf-aria-hidden" }> = [];
  const liveTruthTimestampSubstitutions: Array<Gate04Occurrence & {
    currentHtml: string;
    substitution: "github-observed-at-source-time-advance" | "request-observed-at-time-advance";
  }> = [];
  const decorativePriorMatches: Array<{ occurrence: Gate04Occurrence; sourceBucket: "live-dom-decorative-binding"; bindingKind: "tree-mark-leaf" | "navigation-ordinal"; bindingPredicate: "tree-mark-leaf-glyph" | "sidebar-navigation-ordinal"; bindingCanonicalSha256: string }> = [];
  for (const occurrence of prior) {
    const decoration = exactDecorativeOccurrence(occurrence, "prior");
    if (decoration) {
      const scan = scansByKey.get(`${occurrence.view}|${occurrence.state}`);
      if (!scan) throw new Error(`Gate 0.4 decorative binding scan missing: ${canonicalJson(occurrence)}`);
      const candidates = scan.decorativeBindings.entries.filter((entry) => entry.kind === decoration.kind
        && entry.predicate === decoration.predicate
        && entry.ordinal === decoration.ordinal
        && entry.accessibleName === decoration.accessibleName
        && entry.sourceBucket === "live-dom-decorative-binding"
        && entry.matchCount === 1
        && entry.outerHTML === decoration.currentHtml
        && entry.childElementCount === 0
        && entry.interactiveDescendantCount === 0);
      if (candidates.length !== 1) throw new Error(`Gate 0.4 decorative prior occurrence expected one exact live-DOM binding and found ${candidates.length}: ${canonicalJson(occurrence)}`);
      decorativePriorMatches.push({
        occurrence,
        sourceBucket: "live-dom-decorative-binding",
        bindingKind: decoration.kind,
        bindingPredicate: decoration.predicate,
        bindingCanonicalSha256: scan.decorativeBindings.canonicalSha256
      });
      normalizedMatched.push(occurrence);
      if (decoration.kind === "tree-mark-leaf") substitutions.push({ ...occurrence, currentHtml: decoration.currentHtml, substitution: "tree-mark-leaf-aria-hidden" });
      continue;
    }
    const liveTruthTimestamp = exactLiveTruthTimestampOccurrence(occurrence);
    const currentOccurrence = liveTruthTimestamp ? { ...occurrence, html: liveTruthTimestamp.currentHtml } : occurrence;
    const key = canonicalJson(currentOccurrence);
    const candidates = (currentByKey.get(key) ?? []).filter((index) => !used.has(index));
    if (candidates.length !== 1) throw new Error(`Gate 0.4 occurrence closure expected one current target and found ${candidates.length}: ${key}`);
    used.add(candidates[0]!);
    normalizedMatched.push(occurrence);
    if (liveTruthTimestamp) liveTruthTimestampSubstitutions.push({ ...occurrence, ...liveTruthTimestamp });
  }
  const extras = meaningfulCurrent.filter((_, index) => !used.has(index));
  if (extras.some(({ sourceBucket }) => sourceBucket !== "passes")) throw new Error("Gate 0.4 closure left an unmatched current incomplete target");
  const normalizedDigests = inventoryDigests(normalizedMatched);
  if (canonicalJson(normalizedDigests) !== canonicalJson(expectedProject)) throw new Error(`Gate 0.4 ${project} normalized closure mismatch`);
  const sortedSubstitutions = sortedCanonical(substitutions);
  const sortedLiveTruthTimestampSubstitutions = sortedCanonical(liveTruthTimestampSubstitutions);
  const sortedDecorativePriorMatches = sortedCanonical(decorativePriorMatches);
  const sortedExcludedAxeDecorative = sortedCanonical(excludedAxeDecorative);
  const sortedExtras = sortedCanonical(extras);
  return {
    binding: {
      reportRawSha256: gate04ReportRawSha256,
      attachments: [
        { project: "desktop-chromium", sha256: "0ba237f7284564475063811677645f788650aab83a18142f244ee3760cc7b432", scans: 30 },
        { project: "mobile-chromium", sha256: "0d0ffad60dc467b9ba909601bed0032524433b6309c87ebaa4a2cb07ecbe5bab", scans: 30 }
      ],
      fullInventory: {
        ...inventoryDigests(fullPrior),
        gzipSha256: gate04InventoryGzipSha256,
        gzipBase64: gate04InventoryGzipBase64
      }
    },
    projectBaseline: expectedProject,
    matchedOccurrences: normalizedMatched.length,
    normalizedClosure: normalizedDigests,
    substitutions: {
      count: sortedSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedSubstitutions)}\n`),
      exactKind: "tree-mark-leaf-aria-hidden"
    },
    liveTruthTimestampSubstitutions: {
      count: sortedLiveTruthTimestampSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedLiveTruthTimestampSubstitutions)}\n`),
      exactKinds: ["github-observed-at-source-time-advance", "request-observed-at-time-advance"]
    },
    decorativePriorOccurrences: {
      count: sortedDecorativePriorMatches.length,
      canonicalSha256: sha256(`${canonicalJson(sortedDecorativePriorMatches)}\n`),
      sourceBucket: "live-dom-decorative-binding",
      treeMarkLeaf: sortedDecorativePriorMatches.filter(({ bindingKind }) => bindingKind === "tree-mark-leaf").length,
      navigationOrdinal: sortedDecorativePriorMatches.filter(({ bindingKind }) => bindingKind === "navigation-ordinal").length
    },
    currentColorOccurrences: current.length,
    meaningfulColorOccurrences: meaningfulCurrent.length,
    excludedAxeDecorative: {
      count: sortedExcludedAxeDecorative.length,
      canonicalSha256: sha256(`${canonicalJson(sortedExcludedAxeDecorative)}\n`),
      passes: sortedExcludedAxeDecorative.filter(({ sourceBucket }) => sourceBucket === "passes").length,
      incomplete: sortedExcludedAxeDecorative.filter(({ sourceBucket }) => sourceBucket === "incomplete").length
    },
    additionalPreviouslyPassing: {
      count: sortedExtras.length,
      canonicalSha256: sha256(`${canonicalJson(sortedExtras)}\n`),
      allSourceBucketPasses: true
    },
    missing: [],
    closureStatus: "exact-prior-occurrences-closed"
  };
}

async function expectNoHorizontalOverflow(page: Page, view: string) {
  const widths = await page.evaluate((activeView) => {
    const measure = (element: Element | null) => {
      if (!(element instanceof HTMLElement)) return null;
      const bounds = element.getBoundingClientRect();
      return {
        clientWidth: element.clientWidth,
        scrollWidth: element.scrollWidth,
        left: bounds.left,
        right: bounds.right,
        width: bounds.width
      };
    };
    return {
      view: activeView,
      viewportWidth: window.innerWidth,
      document: measure(document.documentElement),
      body: measure(document.body),
      main: measure(document.querySelector(".command-main")),
      panels: Array.from(document.querySelectorAll(".command-panel, .prototype-card, .owner-input-card, .understanding-card, .recommended-packet")).map((panel, index) => {
        const measured = measure(panel);
        if (!measured) throw new Error(`Expected an HTML panel at index ${index}`);
        return { label: panel.querySelector("h2, h3")?.textContent?.trim() ?? `panel-${index + 1}`, ...measured };
      })
    };
  }, view);
  const diagnostic = JSON.stringify(widths, null, 2);
  for (const [label, measured] of [["document", widths.document], ["body", widths.body], ["main", widths.main]] as const) {
    expect(measured, `${label} missing\n${diagnostic}`).not.toBeNull();
    expect(measured!.scrollWidth, `${label} overflow in ${view}\n${diagnostic}`).toBeLessThanOrEqual(measured!.clientWidth);
    expect(measured!.right, `${label} exceeds viewport in ${view}\n${diagnostic}`).toBeLessThanOrEqual(widths.viewportWidth + 0.5);
  }
  for (const panel of widths.panels) {
    expect(panel.scrollWidth, `panel ${panel.label} overflow in ${view}\n${diagnostic}`).toBeLessThanOrEqual(panel.clientWidth);
    expect(panel.left, `panel ${panel.label} starts outside viewport in ${view}\n${diagnostic}`).toBeGreaterThanOrEqual(-0.5);
    expect(panel.right, `panel ${panel.label} exceeds viewport in ${view}\n${diagnostic}`).toBeLessThanOrEqual(widths.viewportWidth + 0.5);
  }
  return widths;
}

function bucketSummary(scans: AxeScanEvidence[], bucket: "passes" | "violations" | "incomplete" | "inapplicable") {
  const rules = scans.flatMap((scan) => scan[bucket]);
  return { ruleRecords: rules.length, nodes: rules.reduce((total, rule) => total + rule.nodes.length, 0) };
}

async function collectSemanticEvidence(page: Page) {
  await activateView(page, "Tree");
  const treeMark = page.locator(".tree-mark");
  const treeMarkLeaf = page.locator(".tree-mark-leaf");
  const sourceReadback = page.locator(".source-readback");
  const treeMap = page.locator(".tree-map");
  const treeEvidence = {
    treeMark: { role: await treeMark.getAttribute("role"), ariaLabel: await treeMark.getAttribute("aria-label"), leafAriaHidden: await treeMarkLeaf.getAttribute("aria-hidden") },
    sourceReadback: { role: await sourceReadback.getAttribute("role"), ariaLabel: await sourceReadback.getAttribute("aria-label") },
    treeMap: { role: await treeMap.getAttribute("role"), ariaLabel: await treeMap.getAttribute("aria-label") }
  };
  await activateView(page, "Action Center");
  const decisionButtons = page.locator(".decision-buttons");
  const evidence = {
    ...treeEvidence,
    decisionButtons: { role: await decisionButtons.getAttribute("role"), ariaLabel: await decisionButtons.getAttribute("aria-label") }
  };
  expect(evidence).toEqual({
    treeMark: { role: null, ariaLabel: null, leafAriaHidden: "true" },
    sourceReadback: { role: "group", ariaLabel: "Source readback" },
    treeMap: { role: "group", ariaLabel: "Clover Tree program graph" },
    decisionButtons: { role: "group", ariaLabel: "Synthetic owner decision" }
  });
  return evidence;
}

async function writeAccessibilityEvidence(
  page: Page,
  testInfo: TestInfo,
  viewport: { width: number; height: number },
  scans: AxeScanEvidence[],
  semantic: Awaited<ReturnType<typeof collectSemanticEvidence>>,
  keyboard: Record<string, unknown>,
  overflow: unknown[]
) {
  const stateKeys = scans.map(({ view, state }) => `${view}|${state}`);
  expect(stateKeys).toEqual([...exactAxeStateKeys]);
  const adjudications = scans.flatMap(({ view, state, adjudications: entries }) => entries.map((entry) => ({ view, state, ...entry })));
  const unresolved = adjudications.filter(({ classification, passes }) => classification === "unresolved" || !passes);
  const classes = Object.fromEntries(
    [...new Set(adjudications.map(({ classification }) => classification))].sort().map((classification) => [classification, adjudications.filter((entry) => entry.classification === classification).length])
  );
  const exemptions = adjudications.filter(({ exemption }) => exemption !== null).map(({ view, state, ruleId, target, html, messageKey, targetMatch, exemption }) => ({ view, state, ruleId, target, html, messageKey, targetMatch, exemption }));
  const passedRatios = scans.flatMap((scan) => scan.passes.filter(({ id }) => id === "color-contrast").flatMap((rule) => rule.nodes.map((node) => {
    const check = [...node.any, ...node.all, ...node.none].find(({ id }) => id === "color-contrast");
    const data = check?.data && typeof check.data === "object" ? check.data as Record<string, unknown> : {};
    const ratio = typeof data.contrastRatio === "number" ? data.contrastRatio : Number.NaN;
    const threshold = typeof data.expectedContrastRatio === "string" ? Number.parseFloat(data.expectedContrastRatio) : Number.NaN;
    return {
      sourceBucket: "passes" as const,
      view: scan.view,
      state: scan.state,
      target: node.target,
      html: node.html,
      foreground: typeof data.fgColor === "string" ? data.fgColor : null,
      background: typeof data.bgColor === "string" ? data.bgColor : null,
      ratio,
      threshold,
      passes: Number.isFinite(ratio) && Number.isFinite(threshold) && ratio >= threshold
    };
  })));
  const adjudicatedRatios = adjudications.filter(({ classification }) => classification === "measured-contrast").map(({ view, state, ruleId, target, html, messageKey, foreground, background, ratio, threshold, passes }) => ({ sourceBucket: "incomplete-adjudication" as const, view, state, ruleId, target, html, messageKey, foreground, background, ratio, threshold, passes }));
  const ratios = [...passedRatios, ...adjudicatedRatios];
  const runtime = [...(runtimeFindings.get(page) ?? [])];
  const renderedText = await page.locator("body").innerText();
  const privacyPatterns = [
    { id: "absolute-local-path", pattern: /\/Users\//u },
    { id: "private-key", pattern: /BEGIN [A-Z ]*PRIVATE KEY/u },
    { id: "credential", pattern: /\b(?:gh[oprsu]_[A-Za-z0-9]{20,}|sk-(?:proj-)?[A-Za-z0-9_-]{20,})\b/u }
  ];
  const privacyFindings = privacyPatterns.filter(({ pattern }) => pattern.test(renderedText)).map(({ id }) => id);
  expect(runtime).toEqual([]);
  expect(privacyFindings).toEqual([]);
  expect(unresolved).toEqual([]);
  expect(new Set(scans.map(({ axeVersion }) => axeVersion))).toEqual(new Set(["4.13.0"]));

  const head = sourceHead();
  const priorClosure = buildGate04PriorClosure(scans, testInfo.project.name);
  const expectedScreenshots = testInfo.project.name === "desktop-chromium"
    ? ["clover-tree-command-center-desktop-today.png"]
    : ["clover-tree-command-center-mobile-today.png", "clover-tree-command-center-mobile-action-center.png", "clover-tree-command-center-mobile-launch-studio.png"];
  const body = {
    schemaVersion: accessibilityEvidenceSchema,
    source: { repository: "chrisdortch/first", head },
    project: testInfo.project.name,
    viewport,
    exactViews,
    expectedScanCount: expectedAxeScansPerViewport,
    actualScanCount: scans.length,
    exactStateKeys: exactAxeStateKeys,
    stateKeys,
    axeVersion: "4.13.0",
    scans,
    adjudications,
    adjudicationClasses: classes,
    ratios,
    exemptions,
    priorClosure,
    semantic,
    keyboard,
    overflow,
    runtime: { consoleErrors: 0, pageErrors: 0, requestFailures: 0, http5xx: 0, findings: runtime },
    privacy: { publicSanitized: true, privateDataAccessed: false, findings: privacyFindings },
    expectedScreenshots,
    summary: {
      scans: scans.length,
      passes: bucketSummary(scans, "passes"),
      violations: bucketSummary(scans, "violations"),
      incomplete: bucketSummary(scans, "incomplete"),
      inapplicable: bucketSummary(scans, "inapplicable"),
      adjudications: adjudications.length,
      closedContrastRatios: ratios.length,
      exemptions: exemptions.length,
      failingContrast: ratios.filter(({ passes }) => !passes).length,
      unresolved: unresolved.length,
      accessibilityViolations: scans.flatMap(({ violations }) => violations).length,
      consequentialAuthorityGranted: false
    },
    unresolved
  };
  const canonicalSha256 = sha256(`${canonicalJson(body)}\n`);
  const evidence = { ...body, canonicalSha256 };
  if (existsSync(accessibilityEvidenceDirectory) && (!lstatSync(accessibilityEvidenceDirectory).isDirectory() || lstatSync(accessibilityEvidenceDirectory).isSymbolicLink())) throw new Error("Accessibility evidence path is not a safe directory");
  mkdirSync(accessibilityEvidenceDirectory, { recursive: true, mode: 0o755 });
  const evidencePath = path.join(accessibilityEvidenceDirectory, `${testInfo.project.name}.json`);
  if (existsSync(evidencePath) && !lstatSync(evidencePath).isFile()) throw new Error(`Accessibility evidence path is not a regular file: ${evidencePath}`);
  const serialized = `${JSON.stringify(canonicalValue(evidence), null, 2)}\n`;
  writeFileSync(evidencePath, serialized, { mode: 0o644 });
  await testInfo.attach(`clover-tree-accessibility-${testInfo.project.name}.json`, { body: Buffer.from(serialized), contentType: "application/json" });
  return { evidencePath, canonicalSha256 };
}

test.beforeEach(async ({ page }) => {
  const runtimeErrors: string[] = [];
  runtimeFindings.set(page, runtimeErrors);
  page.on("console", (message) => { if (message.type() === "error") runtimeErrors.push(message.text()); });
  page.on("pageerror", (error) => runtimeErrors.push(error.message));
  page.on("requestfailed", (request) => runtimeErrors.push(`${request.method()} ${request.url()} ${request.failure()?.errorText ?? "failed"}`));
  page.on("response", (response) => { if (response.status() >= 500) runtimeErrors.push(`${response.status()} ${response.request().method()} ${response.url()}`); });
  await installLiveTruthRoutes(page, { attestationSourceCommit: "f".repeat(40) });
  await page.goto("/", { waitUntil: "networkidle" });
});

test.afterEach(async ({ page }) => {
  await page.waitForTimeout(25);
  const findings = runtimeFindings.get(page) ?? [];
  expect(findings, findings.join("\n")).toEqual([]);
});

